CIMAL(38, 18)) AS VARCHAR), '0'), '0') ELSE rtrim(CAST(CAST(CASE WHEN abs(CAST(-2.0 AS DOUBLE PRECISION)) >= 1.0E-17 AND abs(CAST(-2.0 AS DOUBLE PRECISION)) < 9.007199254740992E15 THEN CAST(-2.0 AS DOUBLE PRECISION) END AS DECIMAL(38, 18)) AS VARCHAR), '0') END WHEN NOT LOCATE('e', lower(CAST(CAST(-2.0 AS DOUBLE PRECISION) AS VARCHAR))) > 0 AND LOCATE('.', CAST(CAST(-2.0 AS DOUBLE PRECISION) AS VARCHAR)) = 0 THEN concat(CAST(CAST(-2.0 AS DOUBLE PRECISION) AS VARCHAR), '.0') ELSE CAST(CAST(-2.0 AS DOUBLE PRECISION) AS VARCHAR) END)) || CHAR(31)) ELSE sqrt(-2.0) END AS "s"
FROM (
  SELECT *
  FROM TRADES_SCHEMA.TRADES AS "t0"
  LIMIT 1
) AS "t1""}],"resultType":{"_type":"tds","tdsColumns":[{"enumMapping":{},"name":"s","relationalType":"FLOAT","type":"Float"}]}},"serializer":{"name":"pure","version":"vX_X_X"},"templateFunctions":["<#function renderCollection collection separator prefix suffix replacementMap defaultValue><#if collection?size == 0><#return defaultValue></#if><#assign newCollection = collection><#list replacementMap as oldValue, newValue>   <#assign newCollection = collection?map(ele -> ele?replace(oldValue, newValue))></#list><#return prefix + newCollection?join(suffix + separator + prefix) + suffix></#function>","<#function collectionSize collection> <#return collection?size?c> </#function>","<#function optionalVarPlaceHolderOperationSelector optionalParameter trueClause falseClause><#if optionalParameter?has_content || optionalParameter?is_string><#return trueClause><#else><#return falseClause></#if></#function>","<#function varPlaceHolderToString optionalParameter prefix suffix replacementMap defaultValue><#if optionalParameter?is_enumerable && !optionalParameter?has_content><#return defaultValue><#else><#assign newParam = optionalParameter><#list replacementMap as oldValue, newValue>   <#assign newParam = newParam?replace(oldValue, newValue)></#list><#return prefix + newParam + suffix></#if></#function>","<#function equalEnumOperationSelector enumVal inDyna equalDyna><#assign enumList = enumVal?split(",")><#if enumList?size = 1><#return equalDyna><#else><#return inDyna></#if></#function>"]}

